#!/usr/bin/env python3
"""Append new closed UTC days to apps/bitcoin-dca-calculator/data/btc-usd-daily.csv.

Python 3 standard library only. Run from the repository root:

    python3 .github/scripts/update_btc_prices.py          # add missing days
    python3 .github/scripts/update_btc_prices.py --full   # rebuild from 2010-07-18
    python3 .github/scripts/update_btc_prices.py --js-only  # only rewrite data/btc-usd-daily.js

Source: Coin Metrics Community API, PriceUSD (BTC/USD close of each UTC day).
Nothing is written unless the result passes validation: no gaps or duplicates,
starts on 2010-07-18, no unfinished day, recent closes within 5% of Coinbase.
Exit code 1 = nothing written.
"""
import hashlib
import json
import os
import sys
import time
import urllib.parse
import urllib.request
from datetime import date, datetime, timedelta, timezone

DATA_DIR = os.path.join("apps", "bitcoin-dca-calculator", "data")
CSV_PATH = os.path.join(DATA_DIR, "btc-usd-daily.csv")
META_PATH = os.path.join(DATA_DIR, "btc-usd-daily.meta.json")
# Same CSV text + metadata as a script, so the browser tests can load it from a page
# opened straight from disk (file://), where fetch() of the .csv is blocked.
JS_PATH = os.path.join(DATA_DIR, "btc-usd-daily.js")
FIRST_DATE = date(2010, 7, 18)
COINMETRICS = "https://community-api.coinmetrics.io/v4/timeseries/asset-metrics"
COINBASE = "https://api.exchange.coinbase.com/products/BTC-USD/candles"


def get_json(url):
    for attempt in range(3):
        try:
            req = urllib.request.Request(url, headers={"User-Agent": "BitcoinLogbook-price-bot/1.0"})
            with urllib.request.urlopen(req, timeout=60) as res:
                return json.load(res)
        except Exception as err:  # noqa: BLE001 - retry any network error
            if attempt == 2:
                raise
            print(f"retrying after error: {err}")
            time.sleep(3 * (attempt + 1))
    raise RuntimeError(f"unreachable: {url}")


def read_csv():
    rows = []
    if not os.path.exists(CSV_PATH):
        return rows
    with open(CSV_PATH, encoding="utf-8") as fh:
        lines = fh.read().strip().splitlines()
    if not lines or lines[0].strip() != "date,close":
        raise SystemExit("CSV header must be 'date,close'")
    for line in lines[1:]:
        d, c = line.split(",")
        rows.append((date.fromisoformat(d), float(c)))
    return rows


def fetch_coinmetrics(start, end):
    params = {
        "assets": "btc", "metrics": "PriceUSD", "frequency": "1d",
        "start_time": start.isoformat(), "end_time": end.isoformat(),
        "paging_from": "start", "page_size": "10000",
    }
    url = f"{COINMETRICS}?{urllib.parse.urlencode(params)}"
    rows = []
    while url:
        data = get_json(url)
        for item in data.get("data", []):
            if item.get("PriceUSD"):
                rows.append((date.fromisoformat(item["time"][:10]), float(item["PriceUSD"])))
        url = data.get("next_page_url")
    return sorted(r for r in rows if start <= r[0] <= end)


def fetch_coinbase(start, end):
    """Daily closes, max 300 candles per request."""
    out = {}
    cursor = start
    while cursor <= end:
        to = min(cursor + timedelta(days=299), end)
        params = {"granularity": "86400", "start": f"{cursor}T00:00:00Z", "end": f"{to}T00:00:00Z"}
        for candle in get_json(f"{COINBASE}?{urllib.parse.urlencode(params)}"):
            out[datetime.fromtimestamp(candle[0], timezone.utc).date()] = float(candle[4])
        cursor = to + timedelta(days=1)
    return out


def validate(rows, last_closed):
    errors = []
    if not rows:
        return ["no rows"]
    if rows[0][0] != FIRST_DATE:
        errors.append(f"history must start on {FIRST_DATE}, starts on {rows[0][0]}")
    for (d0, _), (d1, c1) in zip(rows, rows[1:]):
        if d1 != d0 + timedelta(days=1):
            errors.append(f"expected {d0 + timedelta(days=1)} after {d0}, got {d1}")
        if not c1 > 0:
            errors.append(f"invalid price on {d1}: {c1}")
    if rows[-1][0] > last_closed:
        errors.append(f"{rows[-1][0]} is not a closed UTC day yet")
    return errors


def write_js_copy():
    """Write data/btc-usd-daily.js from the CSV and metadata files (only if it differs)."""
    with open(CSV_PATH, encoding="utf-8") as fh:
        csv_text = fh.read()
    with open(META_PATH, encoding="utf-8") as fh:
        meta = json.load(fh)
    js_text = (
        "/* Generated by .github/scripts/update_btc_prices.py from btc-usd-daily.csv. Do not edit. */\n"
        "(typeof window !== 'undefined' ? window : globalThis).BTC_USD_DAILY = "
        + json.dumps({"csv": csv_text, "meta": meta}, separators=(",", ":"))
        + ";\n"
    )
    old = open(JS_PATH, encoding="utf-8").read() if os.path.exists(JS_PATH) else ""
    if js_text != old:
        with open(JS_PATH, "w", encoding="utf-8") as fh:
            fh.write(js_text)


def summary(lines):
    text = "\n".join(lines)
    print(text)
    path = os.environ.get("GITHUB_STEP_SUMMARY")
    if path:
        with open(path, "a", encoding="utf-8") as fh:
            fh.write(text + "\n")


def main():
    full = "--full" in sys.argv
    if "--js-only" in sys.argv:  # regenerate data/btc-usd-daily.js without fetching anything
        write_js_copy()
        return
    last_closed = datetime.now(timezone.utc).date() - timedelta(days=1)
    existing = [] if full else read_csv()
    start = existing[-1][0] + timedelta(days=1) if existing else FIRST_DATE

    rows = list(existing)
    if start <= last_closed:
        print(f"Fetching Coin Metrics {start} -> {last_closed}")
        for d, c in fetch_coinmetrics(start, last_closed):
            if rows and d <= rows[-1][0]:
                continue
            rows.append((d, c))

    errors = validate(rows, last_closed)
    if errors:
        summary(["### BTC price update failed validation"] + [f"- {e}" for e in errors[:20]])
        sys.exit(1)

    # Cross-check the newest days (at least 30) against Coinbase.
    added = len(rows) - len(existing)
    check_from = rows[-1][0] - timedelta(days=max(min(added, 300), 30) - 1)
    max_diff = None
    try:
        coinbase = fetch_coinbase(check_from, rows[-1][0])
        diffs = [(d, abs(c / coinbase[d] - 1) * 100) for d, c in rows if d >= check_from and d in coinbase]
        max_diff = max((x for _, x in diffs), default=0.0)
        bad = [f"{d}: {x:.2f}% off Coinbase" for d, x in diffs if x > 5]
        if bad:
            summary(["### BTC price update failed the Coinbase cross-check"] + [f"- {b}" for b in bad])
            sys.exit(1)
    except Exception as err:  # noqa: BLE001 - reference outage should not block the update
        print(f"Coinbase cross-check skipped: {err}")

    csv_text = "date,close\n" + "".join(f"{d.isoformat()},{float(f'{c:.10g}'):.10g}\n" for d, c in rows)
    old_text = open(CSV_PATH, encoding="utf-8").read() if os.path.exists(CSV_PATH) else ""
    changed = csv_text != old_text
    if changed:
        with open(CSV_PATH + ".tmp", "w", encoding="utf-8") as fh:
            fh.write(csv_text)
        os.replace(CSV_PATH + ".tmp", CSV_PATH)
        meta = {
            "file": "btc-usd-daily.csv",
            "description": "BTC/USD daily close, one row per UTC day, from the first traded price.",
            "source": "Coin Metrics Community Data (PriceUSD, daily UTC close)",
            "sourceUrl": "https://coinmetrics.io/community-network-data/",
            "license": "CC BY-NC 4.0",
            "firstDate": rows[0][0].isoformat(),
            "lastDate": rows[-1][0].isoformat(),
            "rows": len(rows),
            "lastClose": float(f"{rows[-1][1]:.10g}"),
            "generatedAt": datetime.now(timezone.utc).isoformat(timespec="seconds"),
            "sha256": hashlib.sha256(csv_text.encode()).hexdigest(),
        }
        if max_diff is not None:
            meta["crossCheck"] = {"reference": "Coinbase Exchange BTC-USD daily close", "maxDiffPct": round(max_diff, 3)}
        with open(META_PATH, "w", encoding="utf-8") as fh:
            json.dump(meta, fh, indent=2)
            fh.write("\n")

    write_js_copy()

    out = os.environ.get("GITHUB_OUTPUT")
    if out:
        with open(out, "a", encoding="utf-8") as fh:
            fh.write(f"changed={'true' if changed else 'false'}\nlast_date={rows[-1][0]}\n")

    summary([
        f"### {'BTC prices updated' if changed else 'BTC prices already current'}",
        f"- {len(rows)} rows, {rows[0][0]} -> {rows[-1][0]} (added {added})",
        f"- Latest close: ${rows[-1][1]:,.2f}",
        f"- Coinbase cross-check max difference: {'n/a' if max_diff is None else f'{max_diff:.2f}%'}",
    ])

    if "--max-age-days" in " ".join(sys.argv):
        limit = int(next(a for a in sys.argv if a.startswith("--max-age-days=")).split("=")[1])
        if (last_closed - rows[-1][0]).days > limit:
            print(f"Data is stale: last row {rows[-1][0]}, latest closed day {last_closed}")
            sys.exit(1)


if __name__ == "__main__":
    main()
